action.command:
docker run --rm -v /workspace/01-frontend:/w -w /w node:20-bookworm node -e "
const fs=require('fs');
const l=JSON.parse(fs.readFileSync('package-lock.json','utf8'));
for (const k of Object.keys(l.packages).filter(k=>k.includes('openapi-ts'))) console.log(k, '->', l.packages[k].version);
" 2>&1 | head; echo ====; grep -rn 'openapi-ts' /workspace/01-frontend/*/package.json | head

